import {trendBuckets} from './dashboard.js';
import {showcaseMarkup,mountShowcase,showcaseStyle,showcaseDocument} from './community-showcase.js';
import {dayOf} from './community-model.js';
import {SCENE_LABELS,defaultGroupScenes,groupScenes} from './scene-routing.js';
export function createCommunityUI({community:c,store,esc:e,icon:i,photo,go,render,showModal,modalHead,modal,toast,askConfirm,openSnapshot,renderShowcaseImage}){
 const actor=()=>store.getState().activeAccount;
 const name=id=>({a:'小叶',b:'小光','demo-grandma':'外婆'}[id]||'群成员');
 const roles={owner:'创建者',admin:'管理员',member:'成员'},types={family:'家庭',work:'工作',other:'兴趣生活'},covers={sun:'sun-line',leaf:'leaf-line',home:'home-heart-line',coffee:'cup-line'};
 const admin=g=>['owner','admin'].includes(c.role(g.id));
 const avatar=(id,cls='')=>`<span class="co-avatar ${cls}">${e(name(id).slice(-1))}</span>`;
 const cover=g=>`<span class="co-cover ${e(g.cover)}">${i(covers[g.cover]||'sun-line')}</span>`;
 const link=(route,label,cls='')=>`<button class="${cls}" data-route="${route}" ${!label.replace(/<[^>]*>/g,'').trim()?`aria-label="${route.startsWith('group-settings/')?'群组设置':route==='group-publish'?'分享海报':'返回'}"`:''}>${label}</button>`;
 const action=(act,label,attrs='',cls='')=>`<button class="${cls}" data-co="${act}" ${attrs}>${label}</button>`;
 const header=(title,back='communities',right='')=>`<header class="co-header">${link(back,i('arrow-left-s-line'),'co-back')}<h1>${e(title)}</h1><div>${right}</div></header>`;
 const empty=(title,body,buttons='')=>`<div class="co-empty">${i('seedling-line')}<h2>${title}</h2><p>${body}</p>${buttons}</div>`;
 const wrap=html=>`<div class="co-page">${html}</div>`;
 const byId=id=>c.get(id);
 const format=t=>new Date(t).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
 let feedFilter='all',postTools=null,commentEditing=null;
 const expandedComments=new Set();
 let trendMetric='posts';
 let selectedPeriod='7',customFrom=dayOf(Date.now()-6*86400000),customTo=dayOf(Date.now());
 const period=()=>selectedPeriod==='custom'?{from:customFrom,to:customTo}:selectedPeriod==='all'?{}:{from:dayOf(Date.now()-(Number(selectedPeriod)-1)*86400000),to:dayOf(Date.now())};
 const members=g=>g.members.map(m=>`<div class="co-member">${avatar(m.id)}<div><strong>${e(name(m.id))}${m.id===actor()?' <small>我</small>':''}</strong><span>${roles[m.role]} · ${dayOf(m.joinedAt)} 加入</span></div>${admin(g)?action('member-menu',i('more-line'),`data-g="${g.id}" data-user="${m.id}" aria-label="管理${e(name(m.id))}"`):''}</div>`).join('');
 const groupAvatar=g=>{const full=Array.isArray(g.members)?g:c.get(g.id);return `<span class="cg-avatar ${e(g.type)}" aria-hidden="true">${full.members.slice(0,4).map((m,index)=>`<span class="cg-face cg-face-${index}">${e(name(m.id).slice(-1))}</span>`).join('')}${full.members.length<4?`<span class="cg-face cg-face-mark">${i(covers[g.cover]||'sun-line')}</span>`:''}</span>`;};
 function list(){const groups=c.list();return wrap(`<div class="cg-list-actions">${link('group-create',i('add-line')+'<span>创建群组</span>','cg-create')}</div><div class="cg-section-label">已加入的群聊 <span>${groups.length}</span></div><section class="cg-list">${groups.length?groups.map(g=>`<article class="cg-list-item">${link('group/'+g.id,`${groupAvatar(g)}<span class="cg-list-copy"><span class="cg-list-title"><strong>${e(g.name)}</strong><em class="cg-role-${g.role}">${roles[g.role]}</em></span><span class="cg-list-meta">${g.members} 位成员<span>·</span>${types[g.type]}群聊</span></span>${i('arrow-right-s-line')}`,'cg-list-main')}${['owner','admin'].includes(g.role)?`<div class="cg-list-manage"><span>${g.pending?`${g.pending} 条入群申请待处理`:'群组管理'}</span>${link('group-stats/'+g.id,i('bar-chart-box-line')+' 社群数据 '+i('arrow-right-s-line'))}</div>`:''}</article>`).join(''):empty('还没有加入群聊','创建群聊，或通过邀请申请加入。',link('group-create','创建群组','co-primary')+action('demo','查看体验社群','','co-text-button'))}</section>`).replace('class="co-page"','class="co-page co-rooms cg-directory"');}
 function showcaseItems(){return c.list().filter(g=>feedFilter==='all'||g.id===feedFilter).flatMap(g=>c.get(g.id).posts.map(p=>({groupId:g.id,postId:p.id,group:g.name,author:name(p.author),title:p.snapshot.title,caption:p.caption,likes:p.likes.map(l=>name(l.user)),comments:p.comments.filter(x=>!x.removed).map(x=>({author:name(x.user),reply:x.replyUser?name(x.replyUser):'',body:x.body})),snapshot:p.snapshot,createdAt:p.createdAt}))).sort((a,b)=>b.createdAt-a.createdAt);}
 async function openShowcase(share=false){const items=showcaseItems();if(!items.length){toast('暂无可展示的作品');return;}toast('正在准备作品展示…');const output=[];for(const item of items){output.push({...item,image:await renderShowcaseImage(item.snapshot)});}const title=feedFilter==='all'?'社群作品':c.get(feedFilter).name;
 if(share){const response=await fetch('/api/showcase-shares',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,items:output})});if(!response.ok)throw Error('分享链接暂时无法生成，请稍后重试');const result=await response.json();const url=new URL(result.path,location.href).href;showModal(`${modalHead('分享作品轮播')}<div class="cs-preview"><div class="cs-poster-stack">${output.slice(0,3).map((x,index)=>`<img src="${e(x.image)}" alt="作品预览 ${index+1}" class="cs-poster-${index}">`).join('')}</div><div class="cs-summary"><strong>${e(title)}</strong><span>${output.length} 份作品 · 全屏轮播</span><small>${i('chat-1-line')} 点赞与评论弹幕</small></div></div><p class="cs-description">把群里的美好，分享给更多人看见。</p><div class="cs-link-box"><label for="co-showcase-link">${i('link')} 分享链接 <span>无需登录即可查看</span></label><input id="co-showcase-link" readonly value="${e(url)}" aria-label="分享链接"></div><div class="cs-actions">${action('copy-showcase',i('file-copy-line')+'<span>复制链接</span>','','cs-copy')}<a href="${e(url)}" target="_blank" rel="noopener" class="cs-open">${i('play-circle-line')}<span>打开预览</span></a></div><p class="cs-footnote">${i('image-line')} 可在平板或大屏打开，展示分享时的作品</p>`,'co-modal cs-share-modal');return;}
 const blob=new Blob([showcaseDocument(output,title)],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('已打开独立展示页');}
 function hub(){
  const groups=c.list();if(feedFilter!=='all'&&!groups.some(g=>g.id===feedFilter))feedFilter='all';
  const visible=groups;
  const posts=visible.flatMap(g=>c.get(g.id).posts.map(p=>({g,p}))).sort((a,b)=>b.p.createdAt-a.p.createdAt);
  return `<div class="co-page co-moments"><header class="co-moments-nav co-social-top">${action('switch-chat',`<span>${e(feedFilter==='all'?'全部群聊':groups.find(g=>g.id===feedFilter)?.name||'群聊')}</span>${i('arrow-down-s-line')}`,'aria-label="切换群聊"','co-top-switch')}<h1>社群</h1>${action('showcase-share',i('share-forward-line')+'<span>分享</span>','aria-label="分享当前群聊轮播"','co-top-share')}</header><style>${showcaseStyle}</style><div class="co-social-banner">${showcaseMarkup(showcaseItems(),{compact:true,imagesOnly:true})}<div class="co-moments-identity"><strong>${e(name(actor()))}</strong>${avatar(actor())}</div></div><div class="co-moments-intro">和家人、伙伴，一起看见日常里的美好</div>${groups.length?(posts.length?posts.map(({g,p})=>momentsPost(c.get(g.id),p)).join(''):empty('把第一份美好，分享给大家','从夸夸集中选择一张已完成的海报。',link('group-publish','分享海报','co-primary'))):empty('和在意的人，分享美好','创建社群或接受邀请，加入后就能看见大家的日常。',action('create','创建群组','','co-primary')+action('join','接受邀请','','co-text-button')+action('demo','查看体验社群','','co-text-button'))}</div>`;
 }
 function momentsPost(g,p){const mine=p.likes.some(l=>l.user===actor()),comments=p.comments.filter(x=>!x.removed),tools=postTools===p.id;return `<article class="co-post co-moments-post">${avatar(p.author)}<div class="co-moments-body"><strong class="co-moments-author">${e(name(p.author))}</strong>${link('group/'+g.id,`${e(g.name)} · ${types[g.type]}`,'co-moments-source')}<p class="co-moments-caption">${e(p.caption||p.snapshot.title)}</p>${action('poster',`<span class="co-poster" data-community-poster="${p.id}" data-g="${g.id}">${photo(p.snapshot.photos[0])}</span>`,`data-g="${g.id}" data-post="${p.id}" aria-label="查看海报：${e(p.snapshot.title)}"`,'co-poster-button')}<footer class="co-moments-footer"><time>${format(p.createdAt)}</time>${p.author===actor()||admin(g)?action('post-menu','删除',`data-g="${g.id}" data-post="${p.id}"`,'co-moments-delete'):''}<div class="co-moments-tools">${tools?`<div class="co-moments-panel">${action('like',i(mine?'heart-fill':'heart-line')+(mine?'取消':'赞'),`data-g="${g.id}" data-post="${p.id}" aria-pressed="${mine}"`)}${action('inline-comment',i('chat-1-line')+'评论',`data-g="${g.id}" data-post="${p.id}"`)}</div>`:''}${action('post-tools',i('more-fill'),`data-post="${p.id}" aria-label="点赞或评论" aria-expanded="${tools}"`,'co-moments-more')}</div></footer>${p.likes.length||comments.length?`<div class="co-moments-social">${p.likes.length?`<div class="co-moments-likes">${i('heart-line')}<span>${p.likes.map(l=>e(name(l.user))).join('，')}</span></div>`:''}${comments.slice(expandedComments.has(p.id)?0:-3).map(x=>`<div class="co-comment-line">${action('comment-item',`<b>${e(name(x.user))}</b>${x.replyUser?`<span>回复</span><b>${e(name(x.replyUser))}</b>`:''}<span>：${e(x.body)}</span>`,`data-g="${g.id}" data-post="${p.id}" data-comment="${x.id}"`,'co-moments-comment')}</div>`).join('')}${comments.length>3&&!expandedComments.has(p.id)?action('expand-comments',`查看全部 ${comments.length} 条评论`,`data-post="${p.id}"`,'co-moments-comment-all'):''}</div>`:''}</div></article>`;}
 function groupPage(g){return `<div class="co-page co-moments cg-detail">${header('群聊详情','group-list',link('group-settings/'+g.id,i('more-line'),'co-back'))}<section class="cg-identity">${groupAvatar(g)}<div><div class="cg-type-label">${types[g.type]}群聊</div><h2>${e(g.name)}</h2><span class="cg-my-role">${g.members.length} 位成员<span>·</span>${roles[c.role(g.id)]}</span></div></section><p class="cg-description">${e(g.description||'每一个普通瞬间，都值得被看见。')}</p><section class="cg-members cg-members-collapsed">${link('group-members/'+g.id,`<span>群成员 <small>· ${g.members.length} 人</small></span>${i('arrow-right-s-line')}`,'cg-members-title')}</section><div class="cg-management ${admin(g)?'cg-management-admin':''}">${link('group-stats/'+g.id,`<span class="cg-tool-icon">${i('bar-chart-box-line')}</span><span>${admin(g)?'社群数据':'我的数据'}</span>${i('arrow-right-s-line')}`)}${admin(g)?link('group-requests/'+g.id,`<span class="cg-tool-icon">${i('user-add-line')}</span><span>入群审核</span>${g.requests.some(r=>r.status==='pending')?'<em class="cg-request-dot"></em>':''}${i('arrow-right-s-line')}`):''}</div><div class="cg-feed-heading"><h2>群动态 <small>${g.posts.length}</small></h2></div>${g.posts.length?g.posts.slice().sort((a,b)=>b.createdAt-a.createdAt).map(p=>postCard(g,p)).join(''):empty('还没有群动态','生成海报时勾选发布到社群，美好就会出现在这里。')}</div>`;}


 function postCard(g,p){return momentsPost(g,p);}
 function comments(g,pid){const p=g.posts.find(p=>p.id===pid);if(!p)return wrap(header('评论','group/'+g.id)+empty('这份动态已撤回','返回群组查看其他美好'));const comments=p.comments.filter(x=>!x.removed);return wrap(`${header('评论','group/'+g.id)}<section class="co-comment-context">${photo(p.snapshot.photos[0])}<div><strong>${e(p.snapshot.title)}</strong><span>${e(name(p.author))}的分享</span></div></section><h2 class="co-subtitle">全部评论 <small>${comments.length}</small></h2>${comments.length?comments.map(x=>`<div class="co-comment">${avatar(x.user)}<div><strong>${e(name(x.user))}</strong><p>${e(x.body)}</p><time>${format(x.at)}</time></div>${x.user===actor()||admin(g)?action('delete-comment','删除',`data-g="${g.id}" data-post="${pid}" data-comment="${x.id}"`):''}</div>`).join(''):empty('第一句鼓励，留给你','具体的看见，就是很好的夸赞。')}<form class="co-comment-form" data-co-form="comment" data-g="${g.id}" data-post="${pid}"><label class="co-sr" for="co-comment-body">评论内容</label><textarea id="co-comment-body" name="body" maxlength="300" required placeholder="送上一句鼓励…"></textarea><button class="co-primary" type="submit">发送</button></form>`);}
 function creation(id){const g=id?byId(id):null;return wrap(`${header(g?'群组资料':'创建群组',g?'group-settings/'+id:'communities')}<div class="co-form-intro"><span class="co-eyebrow">A SPACE FOR YOUR PEOPLE</span><h2>${g?'让社群更有自己的样子':'给美好，一个共同的家'}</h2><p>家人、伙伴，或一群有相同热爱的人。</p></div><form class="co-form" data-co-form="${g?'edit':'create'}" ${g?`data-g="${id}"`:''}><label>群名称<input name="name" maxlength="30" required placeholder="例如：我们这一家" value="${e(g?.name||'')}"></label><label>群类型<select name="type">${Object.entries(types).map(([key,t])=>`<option value="${key}" ${g?.type===key?'selected':''}>${t}</option>`).join('')}</select></label><fieldset class="co-receive-scenes"><legend>关联夸赞场景</legend><p class="co-field-note">成员选择这些场景生成海报时，默认自动发布到本群。</p><div class="co-scene-checkboxes">${Object.entries(SCENE_LABELS).map(([key,label])=>`<label><input type="checkbox" name="scenes" value="${key}" ${(g?groupScenes(g):defaultGroupScenes('family')).includes(key)?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><fieldset><legend>选择群标识</legend><div class="co-cover-picker">${Object.entries(covers).map(([key,ico])=>`<label><input type="radio" name="cover" value="${key}" ${(g?.cover||'sun')===key?'checked':''}><span class="co-cover ${key}">${i(ico)}</span></label>`).join('')}</div></fieldset><label>群简介 <small>选填</small><textarea name="description" maxlength="150" placeholder="说说你们想一起记录什么…">${e(g?.description||'')}</textarea></label><p class="co-field-note">${i('shield-check-line')}新成员需经审核，群内内容仅成员可见。</p><button class="co-primary" type="submit">${g?'保存修改':'创建并邀请成员'}</button></form>`);}
 function invitation(token){const inv=c.invitation(token);return wrap(`${header('群组邀请')}<section class="co-invite-hero">${cover(inv)}<span class="co-eyebrow">一起收藏生活的闪光</span><h2>${e(inv.name)}</h2><p>${e(inv.description)}</p><span class="co-tag">${types[inv.type]} · ${inv.members} 位成员</span></section>${inv.joined?link('group/'+inv.id,'进入群组','co-primary co-wide'):inv.status==='pending'?`<div class="co-info">${i('time-line')}入群申请已提交，等待创建者或管理员审核。</div>`:`<form class="co-form" data-co-form="apply" data-token="${e(token)}">${inv.status==='rejected'?'<p class="co-info">上次申请未通过，可补充说明后重新申请。</p>':''}<label>和大家打个招呼 <small>选填</small><textarea name="message" maxlength="100" placeholder="我是…，很高兴加入你们。"></textarea></label><p class="co-field-note">审核通过后，即可查看群内海报、点赞和评论。</p><button class="co-primary" type="submit">申请加入</button></form>`}`);}
 function requests(g){if(!admin(g))throw Error('仅创建者和管理员可审核');const pending=g.requests.filter(r=>r.status==='pending');return wrap(`${header('入群审核','group/'+g.id)}<div class="co-info">新成员通过审核后，才能浏览群内内容。</div>${pending.length?pending.map(r=>`<article class="co-request">${avatar(r.user)}<div><strong>${e(name(r.user))}</strong><p>${e(r.message||'申请加入群组')}</p><time>${format(r.at)}</time><div class="co-request-actions">${action('reject','拒绝',`data-g="${g.id}" data-user="${r.user}"`,'co-secondary')}${action('approve','通过',`data-g="${g.id}" data-user="${r.user}"`,'co-primary')}</div></div></article>`).join(''):empty('申请都已处理','新的入群申请会出现在这里。')}<h2 class="co-subtitle">最近处理</h2>${g.requests.filter(r=>r.status!=='pending').slice().reverse().map(r=>`<div class="co-history"><span>${e(name(r.user))}</span><small>${r.status==='approved'?'已通过':'已拒绝'}</small></div>`).join('')||'<p class="co-muted">暂无审核记录</p>'}`);}
 function settings(g){return wrap(`${header('群组设置','group/'+g.id)}<section class="co-settings-card">${cover(g)}<h2>${e(g.name)}</h2><p>${types[g.type]} · ${g.members.length} 位成员</p></section><div class="co-menu">${link('group-members/'+g.id,`<span>群成员</span><span>${g.members.length} ${i('arrow-right-s-line')}</span>`)}${admin(g)?`${link('group-edit/'+g.id,`群组资料 ${i('arrow-right-s-line')}`)}${link('group-requests/'+g.id,`入群审核 ${i('arrow-right-s-line')}`)}${action('invite',`邀请成员 ${i('link')}`,`data-g="${g.id}"`)}`:''}${link('group-stats/'+g.id,`${admin(g)?'群组数据看板':'我的数据'} ${i('arrow-right-s-line')}`)}${g.owner===actor()?`${link('group-transfer/'+g.id,`转让群组 ${i('arrow-right-s-line')}`)}${action('dissolve','解散群组',`data-g="${g.id}"`,'co-danger')}`:action('leave','退出群组',`data-g="${g.id}"`,'co-danger')}</div><p class="co-field-note co-pad">群内分享与你的私人夸夸集独立保存。</p>`);}
 function statistics(g,target){const can=admin(g);target=target||(!can?actor():null);const range=period(),data=c.statistics(g.id,{target,...range});const rows=target?[['发布作品',data.posts,'份'],['记录天数',data.days,'天'],['收到点赞',data.likes,'次'],['收到评论',data.comments,'条']]:[['发布作品',data.posts,'份'],['参与成员',data.participatingMembers,'人'],['收到点赞',data.likes,'次'],['收到评论',data.comments,'条']];const metrics={posts:{label:'发布',trend:data.trend,unit:'份'},likes:{label:'点赞',trend:data.likesTrend,unit:'次'},comments:{label:'评论',trend:data.commentsTrend,unit:'条'}},current=metrics[trendMetric],buckets=trendBuckets(current.trend,range.from,range.to),max=Math.max(1,...buckets.map(x=>x.value));const dateLabel=range.from?range.from.replaceAll('-','.')+' — '+range.to.replaceAll('-','.'): '全部记录';return wrap(`${header(target?name(target)+'的数据':'数据看板',target&&can?'group-stats/'+g.id:'group/'+g.id)}<div class="ds-context"><strong>${e(g.name)}</strong><span>${target?'仅统计该成员在本群的数据':g.members.length+' 位群成员 · '+data.days+' 天有发布'}</span></div><div class="co-periods">${[['7','近7天'],['30','近30天'],['all','全部'],['custom','自定义']].map(([value,label])=>action('period',label,`data-value="${value}" aria-pressed="${selectedPeriod===value}"`,selectedPeriod===value?'selected':'')).join('')}</div>${selectedPeriod==='custom'?`<form class="co-date-form" data-co-form="dates"><label>开始<input type="date" name="from" value="${customFrom}" required></label><label>结束<input type="date" name="to" value="${customTo}" required></label><button type="submit">应用</button></form>`:''}<p class="ds-date-range">${dateLabel}</p><section class="ds-metrics">${rows.map(([label,n,unit])=>`<div><span>${label}</span><strong>${n}<small>${unit}</small></strong></div>`).join('')}</section><section class="ds-trend"><div class="ds-section-head"><h2>数据趋势</h2><span>单位：${current.unit}</span></div><div class="ds-trend-tabs">${Object.entries(metrics).map(([key,value])=>action('trend-metric',value.label,`data-value="${key}" aria-pressed="${trendMetric===key}"`,trendMetric===key?'selected':'')).join('')}</div><div class="ds-chart" aria-label="${current.label}趋势">${buckets.map((x,index)=>`<button data-co="trend-point" data-from="${x.from}" data-to="${x.to}" data-count="${x.value}" data-unit="${current.unit}" aria-label="${x.from}${x.to!==x.from?'至'+x.to:''}，${x.value}${current.unit}"><span class="ds-chart-area"><span style="height:${x.value/max*82}px">${x.value?`<b>${x.value}</b>`:''}</span></span><small>${buckets.length<=7||index===0||index===buckets.length-1||index%3===0?x.from.slice(5):'&nbsp;'}</small></button>`).join('')||'<div class="ds-chart-empty">所选期间暂无互动数据</div>'}</div><p class="ds-chart-note">${buckets.some(x=>x.from!==x.to)?'日期已分段汇总 · ':''}点击柱位查看具体日期与数量</p></section>${can&&!target?`<section class="ds-members"><div class="ds-section-head"><h2>成员数据</h2><span>按入群顺序</span></div><label class="ds-search">${i('search-line')}<input id="ds-member-search" type="search" placeholder="搜索成员姓名" aria-label="搜索成员姓名"></label><div class="ds-member-columns"><span>成员</span><span>发布</span><span>获赞</span><span>评论</span><span></span></div>${g.members.map(m=>{const d=c.statistics(g.id,{target:m.id,...range});return link('group-member/'+g.id+'/'+m.id,`<span class="ds-member-identity">${avatar(m.id)}<span><strong>${e(name(m.id))}</strong><small>${roles[m.role]}</small></span></span><b>${d.posts}</b><b>${d.likes}</b><b>${d.comments}</b>${i('arrow-right-s-line')}`,'co-data-member ds-member-row');}).join('')}<p class="ds-search-empty" hidden>没有找到该成员</p></section>`:''}<p class="co-stats-note">${target?'':'参与成员仅统计当前群成员；历史成员的有效作品仍计入发布总量。'}发布按分享时间、互动按发生时间统计，均以当前有效记录为准，不含私人海报与其他群数据。</p>`).replace('class="co-page"','class="co-page ds-page"');}

 function sharePage(gid){const jobs=store.getAccount().jobs.filter(j=>j.status==='done').slice().reverse();return wrap(`${header('选择海报',gid?'group/'+gid:'communities')}<p class="co-pad co-muted">分享已完成的海报，不消耗制作次数。</p>${jobs.length?`<div class="co-pick-grid">${jobs.map(j=>action('share-job',`${photo(j.photos[0])}<strong>${e(j.title||j.text)}</strong><small>${dayOf(j.createdAt)}</small>`,`data-job="${j.id}" ${gid?`data-g="${gid}"`:''}`,'co-pick')).join('')}</div>`:empty('还没有完成的海报','先记录一个美好的瞬间，做好后再分享给大家。',action('start-capture','去生成海报','','co-primary'))}`);}
 function openShare(jobId,gid){const job=store.getAccount().jobs.find(j=>j.id===jobId&&j.status==='done');if(!job)throw Error('请选择已完成的海报');const groups=c.list();showModal(`${modalHead('分享到社群')}<p class="description">只分享你选中的海报和配文，私人记录不会自动公开。</p>${groups.length?`<form data-co-form="share" data-job="${jobId}"><label for="co-share-caption">分享配文 <small>选填</small></label><textarea id="co-share-caption" name="caption" maxlength="300" placeholder="想对大家说点什么…"></textarea><div class="co-share-options">${groups.map(g=>`<label><input type="checkbox" name="groups" value="${g.id}" ${g.id===gid?'checked':''}>${cover(g)}<span><strong>${e(g.name)}</strong><small>${g.members} 位成员</small></span></label>`).join('')}</div><button class="co-primary" type="submit">确认分享</button></form>`:`<div class="co-info">先创建或加入一个群组，就能把美好分享给大家。</div>${link('communities','去看看社群','co-primary co-wide')}`}`,'co-modal');}
 function invite(gid){const token=c.invite(gid),g=c.get(gid);const url=location.href.split('#')[0]+'#invite/'+token;showModal(`${modalHead('邀请加入')}<div class="co-invite-card">${cover(g)}<h3>${e(g.name)}</h3><p>邀请你一起记录生活的美好</p><span>申请后由创建者或管理员审核</span></div><label for="co-invite-link">邀请链接</label><input id="co-invite-link" readonly value="${e(url)}"><div class="buttons">${action('copy-invite','复制邀请链接','','primary')}${link('invite/'+token,'查看邀请','secondary')}</div>`,'co-modal');}
 const renderRoute=route=>{const [page,id,extra]=route.split('/');try{if(page==='communities')return hub();if(page==='group-list')return list().replace('<div class="co-page co-rooms cg-directory">','<div class="co-page co-rooms cg-directory">'+header('我的群组','profile'));if(page==='group-publish')return sharePage();if(page==='group-create')return creation();if(page==='invite')return invitation(id);const g=byId(id);if(page==='group')return groupPage(g);if(page==='group-admins'){if(!admin(g))throw Error('仅创建者和管理员可设置');return wrap(header('设置管理员','group/'+id)+`<p class="co-field-note co-pad">管理员可管理成员、审核入群和查看社群数据，不能解散群组或移除创建者。</p><div class="cg-admin-list">${g.members.map(m=>`<div class="cg-admin-row">${avatar(m.id)}<div><strong>${e(name(m.id))}${m.id===actor()?' · 我':''}</strong><small>${roles[m.role]}</small></div>${m.role==='owner'?'<span class="cg-owner-label">创建者</span>':action('toggle-admin',m.role==='admin'?'撤销管理员':'设为管理员',`data-g="${id}" data-user="${m.id}" data-admin="${m.role!=='admin'}"`,'cg-admin-toggle')}</div>`).join('')}</div>`);}if(page==='group-members')return wrap(header('群成员','group/'+id,admin(g)?action('invite',i('add-line')+'邀请',`data-g="${g.id}"`,'cg-members-invite'):'')+`<label class="cg-member-search">${i('search-line')}<input id="cg-member-search" type="search" placeholder="搜索群成员" aria-label="搜索群成员姓名"></label><p class="co-muted co-pad">${g.members.length} 位成员 · ${admin(g)?'点击 ··· 设置管理员或移除成员':'一起记录，互相鼓励'}</p><div class="cg-search-members">${members(g)}</div><p class="cg-member-search-empty co-muted co-pad" hidden>没有找到该成员</p>`);if(page==='group-edit'){if(!admin(g))throw Error('无权修改群资料');return creation(id);}if(page==='group-settings')return settings(g);if(page==='group-requests')return requests(g);if(page==='group-stats')return statistics(g);if(page==='group-member')return statistics(g,extra);if(page==='group-comments')return comments(g,extra);if(page==='group-share')return sharePage(id);if(page==='group-transfer'){if(g.owner!==actor())throw Error('仅创建者可转让');return wrap(header('转让群组','group-settings/'+id)+`<div class="co-info">新创建者将接管全部管理权限，你将成为管理员，之后可以退出群组。</div>`+g.members.filter(m=>m.id!==actor()).map(m=>action('transfer',`${avatar(m.id)}<strong>${e(name(m.id))}</strong>${i('arrow-right-s-line')}`,`data-g="${id}" data-user="${m.id}"`,'co-transfer-row')).join(''));}return '';}catch(error){return wrap(header('社群')+empty('暂时无法查看',e(error.message),link('communities','返回社群','co-primary')));}};
 function dismissTools(){postTools=null;document.querySelectorAll?.('.co-moments-panel').forEach(x=>x.remove());document.querySelectorAll?.('[data-co="post-tools"]').forEach(x=>x.setAttribute('aria-expanded','false'));}
 function closeComment(){commentEditing=null;document.querySelector?.('#co-inline-comment')?.remove();}
 function mountComment(){
  document.querySelector?.('#co-inline-comment')?.remove();if(!commentEditing)return;
  const edit=commentEditing,g=c.get(edit.group),p=g.posts.find(p=>p.id===edit.post);if(!p){closeComment();toast('动态已撤回');return;}
  const form=document.createElement('form');form.id='co-inline-comment';form.className='co-inline-dock';form.dataset.coForm='inline-comment';form.dataset.g=edit.group;form.dataset.post=edit.post;
  form.innerHTML=`${edit.replyUser?`<div class="co-inline-reply">回复 ${e(name(edit.replyUser))}${action('cancel-inline-comment','取消','aria-label="取消评论"')}</div>`:''}<div class="co-inline-fields"><label class="co-sr" for="co-inline-body">${edit.replyUser?'回复'+e(name(edit.replyUser)):'评论内容'}</label><textarea id="co-inline-body" name="body" maxlength="300" required placeholder="${edit.replyUser?'回复'+e(name(edit.replyUser))+':':'评论…'}">${e(edit.body)}</textarea><button type="submit">发送</button>${!edit.replyUser?action('cancel-inline-comment',i('close-line'),'aria-label="取消评论"'):''}</div>`;
  document.querySelector('.phone').append(form);const input=form.querySelector('textarea');input.addEventListener('input',()=>{if(commentEditing)commentEditing.body=input.value;});queueMicrotask(()=>{input.focus();input.setSelectionRange(input.value.length,input.value.length);});
 }
 function beginComment(gid,pid,reply=null){const g=c.get(gid),p=g.posts.find(p=>p.id===pid);if(!p)throw Error('动态已撤回');const target=reply?p.comments.find(x=>x.id===reply&&!x.removed):null;if(reply&&!target)throw Error('评论已删除');dismissTools();commentEditing={group:gid,post:pid,replyTo:target?.id||null,replyUser:target?.user||null,actor:actor(),route:location.hash.slice(1),body:''};mountComment();}
 function afterRender(route){if(commentEditing&&(commentEditing.route!==route||commentEditing.actor!==actor()))closeComment();else if(commentEditing){try{mountComment();}catch{closeComment();}}}
 document.addEventListener('input',event=>{if(event.target.id==='cg-member-search'){const query=event.target.value.trim().toLocaleLowerCase();let visible=0;for(const row of document.querySelectorAll('.cg-search-members .co-member')){row.hidden=!row.querySelector('strong').textContent.toLocaleLowerCase().includes(query);if(!row.hidden)visible++;}const empty=document.querySelector('.cg-member-search-empty');if(empty)empty.hidden=visible>0;return;}if(event.target.id!=='ds-member-search')return;const query=event.target.value.trim().toLocaleLowerCase(),rows=[...document.querySelectorAll('.ds-member-row')];let visible=0;for(const row of rows){const match=row.querySelector('strong').textContent.toLocaleLowerCase().includes(query);row.hidden=!match;if(match)visible++;}const empty=document.querySelector('.ds-search-empty');if(empty)empty.hidden=visible>0;});
 document.addEventListener('click',event=>{if(!event.target.closest?.('.co-moments-tools'))dismissTools();if(commentEditing&&!event.target.closest?.('.co-inline-dock,[data-co="inline-comment"],[data-co="comment-item"]'))closeComment();});
 let pressTimer=null,pressStart=null,suppressCommentClickUntil=0;
 function closeCommentMenu(){document.querySelector?.('.co-comment-popover')?.remove();}
 function commentMenu(b){try{const g=c.get(b.dataset.g),comment=g.posts.find(p=>p.id===b.dataset.post)?.comments.find(x=>x.id===b.dataset.comment&&!x.removed);if(!comment||comment.user!==actor()&&!admin(g))return;closeComment();closeCommentMenu();const host=b.closest('.co-comment-line');if(!host)return;const menu=document.createElement('div');menu.className='co-comment-popover';menu.setAttribute('role','menu');menu.innerHTML=action('delete-comment','删除',`data-g="${g.id}" data-post="${b.dataset.post}" data-comment="${comment.id}" role="menuitem"`);host.append(menu);suppressCommentClickUntil=Date.now()+800;}catch(error){toast(error.message);}}
 const cancelPress=()=>{clearTimeout(pressTimer);pressTimer=null;};
 document.addEventListener('pointerdown',event=>{cancelPress();const b=event.target.closest?.('[data-co="comment-item"]');if(!b||event.button!==0)return;pressStart={x:event.clientX,y:event.clientY};pressTimer=setTimeout(()=>commentMenu(b),550);});
 document.addEventListener('pointermove',event=>{if(pressStart&&Math.hypot(event.clientX-pressStart.x,event.clientY-pressStart.y)>8)cancelPress();});
 document.addEventListener('pointerup',cancelPress);document.addEventListener('pointercancel',cancelPress);document.addEventListener('scroll',()=>{cancelPress();closeCommentMenu();},true);
 document.addEventListener('click',event=>{if(!event.target.closest?.('.co-comment-popover')&&!(event.target.closest?.('[data-co="comment-item"]')&&Date.now()<suppressCommentClickUntil))closeCommentMenu();});
 document.addEventListener('contextmenu',event=>{const b=event.target.closest?.('[data-co="comment-item"]');if(!b)return;event.preventDefault();cancelPress();commentMenu(b);});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'){dismissTools();closeComment();closeCommentMenu();}});
 async function click(b){if(!b.dataset.co)return false;const act=b.dataset.co,gid=b.dataset.g,user=b.dataset.user,pid=b.dataset.post;try{
 if(act==='inline-comment')beginComment(gid,pid);
 if(act==='reply-comment'){modal.close();beginComment(gid,pid,b.dataset.comment);}
 if(act==='cancel-inline-comment')closeComment();
 if(act==='expand-comments'){expandedComments.add(pid);render();}
 if(act==='comment-item'){
  if(Date.now()<suppressCommentClickUntil)return true;
  const g=c.get(gid),comment=g.posts.find(p=>p.id===pid)?.comments.find(x=>x.id===b.dataset.comment&&!x.removed);if(!comment)throw Error('评论已删除');
  if(comment.user!==actor())beginComment(gid,pid,comment.id);
 }
 if(act==='post-tools'){postTools=postTools===pid?null:pid;render();}
 if(act==='switch-chat'){showModal(`${modalHead('切换群聊')}<div class="co-chat-options">${[{id:'all',name:'全部群聊'},...c.list()].map(g=>action('feed-filter',`${e(g.name)}${feedFilter===g.id?i('check-line'):''}`,`data-value="${g.id}" aria-pressed="${feedFilter===g.id}"`,feedFilter===g.id?'selected':'')).join('')}</div>`,'co-modal');}
 if(act==='feed-filter'){feedFilter=b.dataset.value;postTools=null;modal.close();render();}
 if(act==='create')go('group-create');
 if(act==='join')showModal(`${modalHead('接受群组邀请')}<p class="description">粘贴收到的邀请链接，申请加入群组。</p><form data-co-form="join"><label>邀请链接<input name="url" required placeholder="粘贴邀请链接"></label><button type="submit" class="co-primary">查看邀请</button></form>`,'co-modal');
 if(act==='showcase-open'||act==='showcase-share'){await openShowcase(act==='showcase-share');return;}
 if(act==='copy-showcase'){await navigator.clipboard.writeText(document.querySelector('#co-showcase-link').value);toast('链接已复制');return;}
 if(act==='demo'){c.seedDemo();go('communities');}
 if(act==='invite')invite(gid);
 if(act==='copy-invite'){const field=document.querySelector('#co-invite-link');try{await navigator.clipboard.writeText(field.value);toast('邀请链接已复制');}catch{field.focus();field.select();toast('请复制已选中的邀请链接');}}
 if(act==='like'){c.like(gid,pid);dismissTools();render();}
 if(act==='poster'){const p=c.get(gid).posts.find(p=>p.id===pid);if(!p)throw Error('动态已撤回');await openSnapshot(p.snapshot);}
 if(act==='post-menu')askConfirm('撤回这条动态？','本群的动态与互动将移除，个人海报和其他群分享不受影响。',()=>c.withdraw(gid,pid),'撤回');
 if(act==='delete-comment'){closeCommentMenu();askConfirm('删除这条评论？','删除后，相关评论统计同步更新。',()=>c.deleteComment(gid,pid,b.dataset.comment),'删除');}
 if(act==='approve'||act==='reject'){c.review(gid,user,act==='approve');render();toast(act==='approve'?'已通过入群申请':'已拒绝本次申请');}
 if(act==='member-menu'){const g=c.get(gid),m=g.members.find(m=>m.id===user);showModal(`${modalHead(name(user))}<p class="description">${roles[m.role]}</p>${m.role==='owner'?'<div class="co-info">创建者身份受保护，不能移除或撤销。</div>':`<div class="co-modal-menu">${action('toggle-admin',m.role==='admin'?'撤销管理员':'设为管理员',`data-g="${gid}" data-user="${user}" data-admin="${m.role!=='admin'}"`)}${action('remove-member','移出群组',`data-g="${gid}" data-user="${user}"`,'co-danger')}</div>`}`,'co-modal');}
 if(act==='toggle-admin'){c.setAdmin(gid,user,b.dataset.admin==='true');modal.close();render();toast('成员身份已更新');}
 if(act==='remove-member')askConfirm('移出'+e(name(user))+'？','对方将无法查看本群内容，已发布的历史动态保留。',()=>c.remove(gid,user),'移出');
 if(act==='transfer')askConfirm('转让给'+e(name(user))+'？','对方成为创建者，你将成为管理员。',()=>{c.transfer(gid,user);go('group-settings/'+gid);},'确认转让');
 if(act==='dissolve')askConfirm('解散群组？','所有成员将无法再访问本群，个人夸夸集不受影响。',()=>{c.dissolve(gid);go('communities');},'解散群组');
 if(act==='leave')showModal(`${modalHead('退出群组')}<p class="description">你可以保留群内分享，也可以同时撤回。个人海报不会删除。</p><div class="co-modal-menu">${action('confirm-leave','保留动态，退出群组',`data-g="${gid}" data-withdraw="false"`)}${action('confirm-leave','撤回我的动态并退出',`data-g="${gid}" data-withdraw="true"`,'co-danger')}</div>`,'co-modal');
 if(act==='confirm-leave'){c.leave(gid,b.dataset.withdraw==='true');modal.close();go('communities');toast('已退出群组');}
 if(act==='share-job')openShare(b.dataset.job,gid);
 if(act==='start-capture')go('capture');
 if(act==='trend-metric'){trendMetric=b.dataset.value;render();}
 if(act==='trend-point'){toast(`${b.dataset.from}${b.dataset.from!==b.dataset.to?' 至 '+b.dataset.to:''}：${b.dataset.count}${b.dataset.unit}`);}
 if(act==='period'){selectedPeriod=b.dataset.value;render();}
 }catch(error){toast(error.message);}return true;}
 document.addEventListener('change',event=>{if(event.target.name!=='type'||!event.target.closest?.('form[data-co-form="create"],form[data-co-form="edit"]'))return;const defaults=defaultGroupScenes(event.target.value);event.target.form.querySelectorAll('input[name="scenes"]').forEach(x=>{x.checked=defaults.includes(x.value);});});
 document.addEventListener('submit',event=>{const f=event.target;if(!f.dataset.coForm)return;event.preventDefault();const data=new FormData(f),kind=f.dataset.coForm,gid=f.dataset.g;try{
 if(kind==='create'){const id=c.create({...Object.fromEntries(data),scenes:data.getAll('scenes')});go('group/'+id);setTimeout(()=>invite(id),0);}
 if(kind==='edit'){c.edit(gid,{...Object.fromEntries(data),scenes:data.getAll('scenes')});go('group-settings/'+gid);toast('群资料已更新');}
 if(kind==='join'){const value=String(data.get('url')).trim();const token=value.match(/#invite\/([a-zA-Z0-9-]+)$/)?.[1];if(!token)throw Error('请粘贴有效的群组邀请链接');go('invite/'+token);}
 if(kind==='apply'){c.apply(f.dataset.token,data.get('message'));render();toast('申请已提交，等待审核');}
 if(kind==='inline-comment'){
  if(!commentEditing||commentEditing.actor!==actor())throw Error('身份已变化，请重新评论');
  c.comment(gid,f.dataset.post,data.get('body'),commentEditing.replyTo);closeComment();render();toast('评论已发送');
 }
 if(kind==='comment'){c.comment(gid,f.dataset.post,data.get('body'));render();toast('评论已发送');}
 if(kind==='share'){const j=store.getAccount().jobs.find(j=>j.id===f.dataset.job);if(!j)throw Error('海报已删除，请重新选择');const n=c.share(data.getAll('groups'),{...j,author:actor()},data.get('caption'));modal.close();go('group/'+data.getAll('groups')[0]);toast(`已分享到 ${n} 个群组`);}
 if(kind==='dates'){const from=String(data.get('from')),to=String(data.get('to'));if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to)throw Error('请选择有效的日期范围');if((Date.parse(to)-Date.parse(from))/86400000>365)throw Error('自定义时间范围最多一年');customFrom=from;customTo=to;render();}
 }catch(error){toast(error.message);}});
 return {render:renderRoute,click,openShare,afterRender:route=>{afterRender(route);const root=document.querySelector('.showcase');if(root)mountShowcase(root);},isRoute:route=>/^(communities|group(?:-[a-z]+)?|invite)(\/|$)/.test(route),posterSnapshots:()=>[...document.querySelectorAll('[data-community-poster]')].map(host=>({host,snapshot:c.get(host.dataset.g).posts.find(p=>p.id===host.dataset.communityPoster)?.snapshot}))};
}
